package com.wedo.backend.discussion.controller;
import com.wedo.backend.discussion.dto.*; import com.wedo.backend.discussion.service.DiscussionService; import com.wedo.backend.security.AuthenticatedUserPrincipal; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class DiscussionController { private final DiscussionService service; public DiscussionController(DiscussionService service){this.service=service;} @GetMapping("/activities/{activityId}/comments") public ActivityDiscussionResponse list(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID activityId){return service.list(activityId,p.userId());} @PostMapping("/activities/{activityId}/comments") public ResponseEntity<CommentResponse> create(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID activityId,@Valid @RequestBody CreateCommentRequest r){return ResponseEntity.status(201).body(service.create(activityId,p.userId(),r));} @PostMapping("/comments/{commentId}/replies") public ResponseEntity<CommentResponse> reply(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID commentId,@Valid @RequestBody CreateCommentRequest r){return ResponseEntity.status(201).body(service.reply(commentId,p.userId(),r));} @PatchMapping("/comments/{commentId}") public CommentResponse update(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID commentId,@Valid @RequestBody UpdateCommentRequest r){return service.update(commentId,p.userId(),r);} @DeleteMapping("/comments/{commentId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID commentId){service.delete(commentId,p.userId());} }
